/**
 * @file src/ui/bagEggDisplay.ts
 * Incremental bag egg/incubator DOM — no BAG_CHANGED (preserves inventory grid).
 */

import type { GameRuntime } from '../types/game.js';

/** Sync incubators + egg inventory rows without publishing bag inventory. */
export function syncBagEggSectionsUI(game: GameRuntime | null | undefined): void {
    if (!game) return;
    if (typeof game.updateIncubatorsDisplay === 'function') {
        game.updateIncubatorsDisplay();
    }
    if (typeof game.syncEggsInventoryDisplay === 'function') {
        game.syncEggsInventoryDisplay();
    } else if (typeof game.updateEggsDisplay === 'function') {
        game.updateEggsDisplay();
    }
}
